"""Bridge to the Hub: export a mesh we generated as a scene file.

Run:  python export_scene.py
Out:  ../../scenes/3d-torus-from-python.json

The same vertices + triangles our renderer drew are handed to the Hub, which draws
them with the GPU (WebGL). Same data, two renderers — yours and the GPU's.
"""
import json
import os

from lab3d.meshes import torus

vertices, tris = torus(1.0, 0.38, 36, 18)
scene = {
    "spec": "arzin-scene/0",
    "id": "3d-torus-from-python",
    "title": "Torus from Python",
    "track": "3d",
    "description": "Generated by modules/01-3d-from-scratch/export_scene.py — the exact "
                   "mesh step3_shaded.py rasterizes on the CPU, now drawn by the GPU. "
                   "Toggle wireframe to see the triangles.",
    "camera": {"position": [0, 2.2, 3.6], "target": [0, 0, 0]},
    "objects": [
        {"type": "grid", "size": 6},
        {"type": "mesh",
         "vertices": [[round(c, 4) for c in v] for v in vertices],
         "triangles": [list(t) for t in tris],
         "color": "#6ec8ff", "flat": True, "spin": [0, 0.4, 0]},
        {"type": "label", "text": f"{len(vertices)} vertices · {len(tris)} triangles",
         "position": [0, 1.0, 0]},
    ],
}
path = os.path.join(os.path.dirname(__file__), "..", "..", "scenes", "3d-torus-from-python.json")
with open(path, "w") as f:
    json.dump(scene, f, separators=(",", ":"))
print("Saved", os.path.normpath(path))
